SET NAMES utf8mb4;
START TRANSACTION;

INSERT INTO Planes_Estudio (Plan_Nombre, Plan_Descripcion) VALUES ('Estadística', 'Unidad 6 del libro: organización de datos y medidas de tendencia central.');
SET @plan_id = LAST_INSERT_ID();

-- Tema 1: Organización de datos
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Organización de datos', 10, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 1.1: Población y muestra
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Población y muestra', 'El profesor de educación física quiere saber cuántos estudiantes de primero básico quieren entrar al club de fútbol. Para averiguarlo, entrevista a 50 estudiantes elegidos al azar.\n\n- **Población:** el conjunto de **todos** los individuos que interesan. Aquí son todos los estudiantes de primero básico.\n- **Muestra:** una **parte** de la población que la representa. Aquí son los 50 estudiantes entrevistados.\n\n> Se usa una muestra cuando es difícil o muy costoso preguntarle a toda la población.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Población y muestra\n\n```pregunta\ntipo: opcion\nenunciado: Para saber qué opinan los aficionados guatemaltecos sobre un partido, se entrevistó a 400 aficionados. ¿Cuál es la **muestra**?\nopciones:\n- [x] Los 400 aficionados entrevistados\n- [ ] Todos los aficionados guatemaltecos\n- [ ] Los jugadores del partido\nexplicacion: La muestra es la parte de la población a la que se le preguntó.\n```\n\n```pregunta\ntipo: opcion\nenunciado: En la misma encuesta de los 400 aficionados, ¿cuál es la **población**?\nopciones:\n- [ ] Los 400 aficionados entrevistados\n- [x] Todos los aficionados guatemaltecos\n- [ ] Los jugadores del partido\nexplicacion: La población son todos los que interesan al estudio.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Un director quiere saber cuántos estudiantes de su instituto quieren participar en una mañana deportiva y entrevista a 60 estudiantes al azar. Los 60 estudiantes son…\nopciones:\n- [x] La muestra\n- [ ] La población\nmezclar: no\nexplicacion: Son solo una parte de todos los estudiantes del instituto.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se llama una parte de la población que refleja sus mismas características?\nopciones:\n- [x] Muestra\n- [ ] Frecuencia\n- [ ] Moda\nexplicacion: A esa parte representativa se le llama muestra.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.2: Tabla de frecuencias
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Tabla de frecuencias', 'En un corral, 20 gallinas pusieron estas cantidades de huevos en 15 días:\n\n9, 8, 5, 8, 7, 9, 8, 10, 7, 10, 11, 7, 8, 10, 8, 6, 7, 6, 8, 9\n\nSe cuenta cuántas gallinas pusieron cada cantidad:\n\n| Huevos | 5 | 6 | 7 | 8 | 9 | 10 | 11 |\n|---|---|---|---|---|---|---|---|\n| Gallinas | 1 | 2 | 4 | **6** | 3 | 3 | 1 |\n\nAl número de veces que aparece un valor se le llama **frecuencia**. La **tabla de frecuencias** resume los valores y sus frecuencias.\n\nEn este caso, la mayor frecuencia es 6: seis gallinas pusieron 8 huevos cada una.\n\n> **Comprobación:** la suma de las frecuencias es el total de datos: $1 + 2 + 4 + 6 + 3 + 3 + 1 = 20$.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Tabla de frecuencias\n\nGoles anotados en 15 jornadas de la Liga Mayor de Fútbol de Guatemala:\n\n**7, 6, 8, 9, 11, 3, 9, 7, 5, 8, 6, 4, 9, 10, 13**\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es la frecuencia del valor 9 (en cuántas jornadas se anotaron 9 goles)?\nrespuesta: 3\nexplicacion: El 9 aparece 3 veces en la lista.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿En cuántas jornadas se anotaron 7 goles?\nrespuesta: 2\nexplicacion: El 7 aparece 2 veces.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿En cuántas jornadas se anotaron 12 goles?\nrespuesta: 0\nexplicacion: El 12 no aparece en la lista, su frecuencia es 0.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuánto suman todas las frecuencias de la tabla?\nrespuesta: 15\nexplicacion: La suma de las frecuencias es el total de datos: 15 jornadas.\n```', FALSE, LAST_INSERT_ID());

-- Tema 2: Medidas de tendencia central
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Medidas de tendencia central', 20, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 2.1: Media aritmética
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Media aritmética', 'Una panadería atendió estos clientes en 11 días:\n\n14, 23, 38, 38, 19, 31, 49, 26, 24, 30, 38\n\nPara saber cuántos clientes atiende **en promedio** por día, se suman todos los datos y se divide entre la cantidad de datos:\n\n$$\\bar{x} = \\frac{330}{11} = 30$$\n\nLa **media aritmética** (o **promedio**) se representa con $\\bar{x}$:\n\n$$\\bar{x} = \\frac{\\text{suma de todos los datos}}{\\text{número de datos}}$$', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Media aritmética\n\n```pregunta\ntipo: numero\nenunciado: Las notas de un estudiante fueron 70, 80, 90 y 60. ¿Cuál es su media aritmética?\nrespuesta: 75\nexplicacion: $\\frac{70 + 80 + 90 + 60}{4} = \\frac{300}{4} = 75$\n```\n\n```pregunta\ntipo: numero\nvariables: k = 10..30, d = 1..9\nenunciado: Encuentra la media aritmética de [[k-d]], [[k]] y [[k+d]].\nrespuesta: k\nexplicacion: $\\frac{[[k-d]] + [[k]] + [[k+d]]}{3} = \\frac{[[3*k]]}{3} = [[k]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Una tienda vendió 13, 22, 24 y 21 refrescos en 4 días. ¿Cuál es el promedio de refrescos vendidos por día?\nrespuesta: 20\nexplicacion: $\\frac{13 + 22 + 24 + 21}{4} = \\frac{80}{4} = 20$\n```\n\n```pregunta\ntipo: numero\nenunciado: La media de 4 datos es 25. ¿Cuánto suman los 4 datos?\nrespuesta: 100\nexplicacion: Si $\\frac{\\text{suma}}{4} = 25$, entonces la suma es $25 \\times 4 = 100$.\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.2: Mediana
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Mediana', 'La **mediana** es el valor que queda **en el centro** cuando los datos se ordenan de menor a mayor.\n\n**Cantidad impar de datos:** se toma el dato del centro.\n\n14, 19, 23, 24, 26, **30**, 31, 38, 38, 38, 49 → mediana = 30 (hay 11 datos y está en el 6.º lugar).\n\n**Cantidad par de datos:** hay dos datos en el centro; se calcula su promedio.\n\n13, 20, 21, 22, 24, **24**, **28**, 29, 30, 34, 46, 57 → mediana = $\\frac{24 + 28}{2} = 26$\n\n> **Recuerda:** ¡siempre ordena los datos primero!', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Mediana\n\n```pregunta\ntipo: numero\nenunciado: Encuentra la mediana de: 5, 9, 2, 7, 4\nrespuesta: 5\nexplicacion: Ordenados: 2, 4, **5**, 7, 9. El dato del centro es 5.\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra la mediana de: 3, 8, 6, 10\nrespuesta: 7\nexplicacion: Ordenados: 3, **6**, **8**, 10. Promedio de los dos centrales: $\\frac{6 + 8}{2} = 7$.\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra la mediana de: 14, 23, 38, 38, 19, 31, 49, 26, 24, 30, 38\nrespuesta: 30\nexplicacion: Ordenados: 14, 19, 23, 24, 26, **30**, 31, 38, 38, 38, 49. El 6.º dato es 30.\n```\n\n```pregunta\ntipo: numero\nvariables: a = 1..9, b = 10|12|14|16|18, c = 20|22|24|26|28, d = 30..39\nenunciado: Encuentra la mediana de: [[c]], [[a]], [[d]], [[b]]\nrespuesta: (b + c) / 2\nexplicacion: Ordenados: [[a]], **[[b]]**, **[[c]]**, [[d]]. $\\frac{[[b]] + [[c]]}{2} = [[(b+c)/2]]$\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.3: Moda
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Moda', 'La **moda** es el valor que **más se repite** en un conjunto de datos (el de mayor frecuencia).\n\n**Ejemplo:** 14, 23, **38**, **38**, 19, 32, 49, 26, 24, 30, **38**\n\nEl 38 aparece 3 veces, más que cualquier otro valor. La moda es 38.\n\n> Si todos los datos aparecen la misma cantidad de veces, se dice que **no hay moda**.\n\n**Resumen de las medidas de tendencia central:**\n\n| Medida | Qué es |\n|---|---|\n| Media | El promedio |\n| Mediana | El dato del centro |\n| Moda | El dato que más se repite |', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Moda\n\n```pregunta\ntipo: numero\nenunciado: Ventas en quetzales de una tienda en 15 días: 125, 35, 50, 40, 80, 125, 70, 50, 125, 75, 80, 90, 80, 80, 35. ¿Cuál es la moda?\nrespuesta: 80\nexplicacion: El 80 aparece 4 veces; el 125, 3 veces; el resto, menos.\n```\n\n```pregunta\ntipo: numero\nenunciado: Ventas de otra sucursal: 100, 75, 50, 80, 60, 40, 70, 75, 140, 90, 75, 70, 150, 50, 90. ¿Cuál es la moda?\nrespuesta: 75\nexplicacion: El 75 aparece 3 veces; el 50, el 70 y el 90 solo 2 veces.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es la moda de: 4, 7, 7, 2, 4, 7?\nrespuesta: 7\nexplicacion: El 7 aparece 3 veces y el 4 solo 2.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es la moda de: 2, 4, 6, 8?\nopciones:\n- [ ] 2\n- [ ] 5\n- [ ] 8\n- [x] No tiene moda\nmezclar: no\nexplicacion: Todos los datos aparecen una sola vez, así que no hay moda.\n```', FALSE, LAST_INSERT_ID());

COMMIT;

SELECT p.Plan_Id, p.Plan_Nombre, COUNT(DISTINCT t.Tema_Id) AS Temas, COUNT(DISTINCT l.Leccion_Id) AS Lecciones, COUNT(e.Ejercicio_Id) AS Ejercicios
FROM Planes_Estudio p JOIN Temas t ON t.Plan_Id = p.Plan_Id JOIN Lecciones l ON l.Tema_Id = t.Tema_Id
LEFT JOIN Ejercicios e ON e.Leccion_Id = l.Leccion_Id WHERE p.Plan_Id = @plan_id GROUP BY p.Plan_Id, p.Plan_Nombre;
